interface EmployeeFormDataItem {
  unit: string;
  item_description: string;
  quantity: number;
  unit_cost: number;
  total_cost: number;
}

interface EmployeeFormData {
  entity_name: string;
  fund_cluster: string;
  office_section: string;
  responsibility_center_code: string;
  date: string;
  remark: string;
  items: EmployeeFormDataItem[];
}

const Orders: React.FC = () => {
  const navigate = useNavigate();
  const { user } = useAuth();
  const [orders, setOrders] = useState<PurchaseOrder[]>([]);
  const [suppliers, setSuppliers] = useState<Supplier[]>([]);
  const [products, setProducts] = useState<Product[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [showModal, setShowModal] = useState(false);
  const [editingOrder, setEditingOrder] = useState<PurchaseOrder | null>(null);
  const [showToast, setShowToast] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');
  const [toastMessage, setToastMessage] = useState('');
  const [toastType, setToastType] = useState<'success' | 'error' | 'warning' | 'info'>('info');
  const [usingMockData, setUsingMockData] = useState(false);
  const [showItemsModal, setShowItemsModal] = useState(false);
  const [selectedRequestItems, setSelectedRequestItems] = useState<any[]>([]);

  // Form state
  const [formData, setFormData] = useState<CreateOrderData>({
    supplier_id: 0,
    delivery_address: '',
    notes: '',
    items: []
  });

  // Employee purchase request form state
  const [employeeFormData, setEmployeeFormData] = useState<EmployeeFormData>({
    entity_name: user?.full_name || user?.username || '',
    fund_cluster: '',
    office_section: user?.department || '',
    responsibility_center_code: '',
    date: new Date().toLocaleDateString('en-US', { month: '2-digit', day: '2-digit', year: 'numeric' }).replace(/\//g, '/'),
    remark: '',
    items: Array(4).fill(null).map(() => ({
      unit: '',
      item_description: '',
      quantity: 0,
      unit_cost: 0.0,
      total_cost: 0.0
    }))
  });

  // Form validation
  const [errors, setErrors] = useState<{
    supplier_id?: string;
    delivery_address?: string;
    notes?: string;
    items?: string;
  }>({});

  // Convert purchase requests (from backend) into the purchase order shape
  const mapPurchaseRequestsToOrders = (purchaseRequests: PurchaseRequest[]): PurchaseOrder[] => {
    return purchaseRequests.map((pr: PurchaseRequest) => ({
      id: parseInt(pr.id) || hashString(pr.id),
      po_number: pr.pr_number,
      supplier_id: 0,
      supplier: {
        id: 0,
        name: pr.entity_name || pr.requested_by || 'N/A',
        address: '',
        province: '',
        contact_person: '',
        phone: '',
        bir_tin: '',
        is_active: true,
        created_at: pr.date_created,
        updated_at: pr.date_updated || pr.date_created
      },
      delivery_address: pr.office_section,
      notes: pr.remark || '',
      status:
        pr.status === 'Pending'
          ? 'Pending'
          : pr.status === 'Approved'
            ? 'Approved'
            : pr.status === 'Completed'
              ? 'Completed'
              : 'Draft',
      total_amount: pr.total_amount,
      date_created: pr.date_created,
      date_updated: pr.date_updated || pr.date_created,
      items: pr.items.map((item, index) => ({
        id: index + 1,
        product_id: index + 1,
        product: {
          id: index + 1,
          name: item.item_description,
          unit: item.unit,
          unit_price: item.unit_cost,
          category: '',
          is_active: true
        },
        quantity: item.quantity,
        unit_price: item.unit_cost,
        total_price: item.total_cost
      }))
    }));
  };

  // Helper function to hash string to number
  const hashString = (str: string): number => {
    let hash = 0;
    for (let i = 0; i < str.length; i++) {
      const char = str.charCodeAt(i);
      hash = ((hash << 5) - hash) + char;
      hash = hash & hash; // Convert to 32bit integer
    }
    return Math.abs(hash);
  };

  useEffect(() => {
    fetchData();
  }, []);

  useEffect(() => {
    // Update employee form data when user changes
    if (user) {
      setEmployeeFormData({
        ...employeeFormData,
        entity_name: user.full_name || user.username || '',
        office_section: user.department || '',
        date: new Date().toLocaleDateString('en-US', { month: '2-digit', day: '2-digit', year: 'numeric' }).replace(/\//g, '/')
      });
    }
  }, [user]);

  const fetchData = async () => {
    try {
      setLoading(true);
      
      // Try to fetch from API first
      try {
        if (user?.role === 'employee') {
          // For employees, fetch their own purchase requests
          console.log('📥 Fetching purchase requests for employee...');
          const purchaseRequests = await apiService.getPurchaseRequests(true);
          console.log('✅ Fetched purchase requests:', purchaseRequests);
          const convertedOrders: PurchaseOrder[] = mapPurchaseRequestsToOrders(purchaseRequests);
          setOrders(convertedOrders);
          setUsingMockData(false);
        } else if (user?.role === 'canvasser') {
          // For canvassers, use real-time PRs and show only "Completed" (ready for Purchase Order stage)
          console.log('📥 Fetching purchase requests for canvasser...');
          const purchaseRequests = await apiService.getPurchaseRequests(false);
          console.log('✅ Fetched purchase requests:', purchaseRequests);
          const convertedOrders: PurchaseOrder[] = mapPurchaseRequestsToOrders(purchaseRequests).filter(
            (o) => o.status === 'Completed'
          );
          setOrders(convertedOrders);
          setUsingMockData(false);
        } else {
          // For other roles, fetch purchase orders (if backend supports it)
          const [ordersData, suppliersData, productsData] = await Promise.all([
            apiService.getOrders(),
            apiService.getSuppliers(),
            apiService.getProducts()
          ]);
          setOrders(ordersData);
          setSuppliers(suppliersData);
          setProducts(productsData);
          setUsingMockData(false);
        }
      } catch (apiError) {
        console.log('API not available, using mock data...', apiError);
        // Use mock data if API fails
        setOrders(mockOrders);
        setSuppliers(mockSuppliers);
        setProducts(mockProducts);
        setUsingMockData(true);
      }
    } catch (error) {
      console.error('Failed to fetch data:', error);
      // Fallback to mock data
      setOrders(mockOrders);
      setSuppliers(mockSuppliers);
      setProducts(mockProducts);
      setUsingMockData(true);
      setError(null);
    } finally {
      setLoading(false);
    }
  };

  const validateForm = (): boolean => {
    const newErrors: {
      supplier_id?: string;
      delivery_address?: string;
      notes?: string;
      items?: string;
    } = {};

    if (!formData.supplier_id) {
      newErrors.supplier_id = 'Supplier is required';
    }

    if (!formData.delivery_address.trim()) {
      newErrors.delivery_address = 'Delivery address is required';
    }

    if (formData.items.length === 0) {
      newErrors.items = 'At least one item is required';
    }

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    
    // Handle employee purchase request form
    if (user?.role === 'employee') {
      try {
        // Calculate total from employee form items
        const totalAmount = employeeFormData.items.reduce((sum, item) => sum + item.total_cost, 0);
        
        // Prepare purchase request data
        const purchaseRequestData: CreatePurchaseRequestData = {
          entity_name: employeeFormData.entity_name,
          fund_cluster: employeeFormData.fund_cluster,
          office_section: employeeFormData.office_section,
          responsibility_center_code: employeeFormData.responsibility_center_code,
          date: employeeFormData.date,
          remark: employeeFormData.remark || employeeFormData.fund_cluster || 'No remarks',
          items: employeeFormData.items
            .filter(item => item.item_description && item.quantity > 0)
            .map(item => ({
              unit: item.unit,
              item_description: item.item_description,
              quantity: item.quantity,
              unit_cost: item.unit_cost,
              total_cost: item.total_cost
            }))
        };

        if (usingMockData) {
          // Simulate API call for mock data
          const year = new Date().getFullYear();
          const prCount = orders.filter(o => o.po_number.startsWith(`PR-${year}-`)).length + 1;
          const prNumber = `PR-${year}-${String(prCount).padStart(3, '0')}`;
          
          const newOrder: PurchaseOrder = {
            id: orders.length + 1,
            po_number: prNumber,
            supplier_id: 0,
            supplier: { id: 0, name: employeeFormData.entity_name, address: '', province: '', contact_person: '', phone: '', bir_tin: '', is_active: true, created_at: '', updated_at: '' },
            delivery_address: employeeFormData.office_section,
            notes: employeeFormData.fund_cluster || 'No remarks',
            status: 'Pending',
            total_amount: totalAmount,
            date_created: new Date().toISOString(),
            date_updated: new Date().toISOString(),
            items: purchaseRequestData.items.map((item, index) => ({
              id: index + 1,
              product_id: index + 1,
              product: { id: index + 1, name: item.item_description, unit: item.unit, unit_price: item.unit_cost, category: '', is_active: true },
              quantity: item.quantity,
              unit_price: item.unit_cost,
              total_price: item.total_cost
            }))
          };

          setOrders([...orders, newOrder]);
          setToastMessage('Purchase request submitted successfully (Demo)');
        } else {
          // Real API call - save to purchase_requests collection
          console.log('📤 Submitting purchase request to backend:', purchaseRequestData);
          const createdPR = await apiService.createPurchaseRequest(purchaseRequestData);
          console.log('✅ Purchase request created successfully:', createdPR);
          setToastMessage('Purchase request submitted successfully');
          // Refresh the list to show the new request
          await fetchData();
        }
        
        setToastType('success');
        setShowToast(true);
        setShowModal(false);
        resetForm();
      } catch (error: any) {
        console.error('Failed to submit purchase request:', error);
        setToastMessage(error.response?.data?.message || 'Failed to submit purchase request');
        setToastType('error');
        setShowToast(true);
      }
      return;
    }
    
    // Original form validation and submission for non-employee roles
    if (!validateForm()) return;

    try {
      if (usingMockData) {
        // Simulate API call for mock data
        const newOrder: PurchaseOrder = {
          id: orders.length + 1,
          po_number: `PO-${new Date().toISOString().slice(0, 10).replace(/-/g, '')}-${String(orders.length + 1).padStart(3, '0')}`,
          supplier_id: formData.supplier_id,
          supplier: suppliers.find(s => s.id === formData.supplier_id)!,
          delivery_address: formData.delivery_address,
          notes: formData.notes || '',
          status: 'Draft',
          total_amount: formData.items.reduce((sum, item) => sum + (item.quantity * item.unit_price), 0),
          date_created: new Date().toISOString(),
          date_updated: new Date().toISOString(),
          items: formData.items.map((item, index) => ({
            id: index + 1,
            product_id: item.product_id,
            product: products.find(p => p.id === item.product_id)!,
            quantity: item.quantity,
            unit_price: item.unit_price,
            total_price: item.quantity * item.unit_price
          }))
        };

        if (editingOrder) {
          setOrders(orders.map(order => order.id === editingOrder.id ? { ...newOrder, id: editingOrder.id } : order));
          setToastMessage('Purchase order updated successfully (Demo)');
        } else {
          setOrders([...orders, newOrder]);
          setToastMessage('Purchase order created successfully (Demo)');
        }
      } else {
        // Real API call
        if (editingOrder) {
          await apiService.updateOrder(editingOrder.id, formData);
          setToastMessage('Purchase order updated successfully');
        } else {
          await apiService.createOrder(formData);
          setToastMessage('Purchase order created successfully');
        }
        fetchData();
      }
      
      setToastType('success');
      setShowToast(true);
      setShowModal(false);
      resetForm();
    } catch (error: any) {
      console.error('Failed to save order:', error);
      setToastMessage(error.response?.data?.message || 'Failed to save order');
      setToastType('error');
      setShowToast(true);
    }
  };

  const handleApprove = async (id: number) => {
    try {
      if (usingMockData) {
        // Simulate approval for mock data
        setOrders(orders.map(order => 
          order.id === id ? { ...order, status: 'Approved' as const } : order
        ));
        setToastMessage('Purchase order approved successfully (Demo)');
      } else {
        await apiService.approveOrder(id);
        setToastMessage('Purchase order approved successfully');
        fetchData();
      }
      setToastType('success');
      setShowToast(true);
    } catch (error: any) {
      console.error('Failed to approve order:', error);
      setToastMessage(error.response?.data?.message || 'Failed to approve order');
      setToastType('error');
      setShowToast(true);
    }
  };

  const handleDelete = async (id: number) => {
    if (!window.confirm('Are you sure you want to delete this purchase order?')) return;

    try {
      if (usingMockData) {
        // Simulate deletion for mock data
        setOrders(orders.filter(order => order.id !== id));
        setToastMessage('Purchase order deleted successfully (Demo)');
      } else {
        await apiService.deleteOrder(id);
        setToastMessage('Purchase order deleted successfully');
        fetchData();
      }
      setToastType('success');
      setShowToast(true);
    } catch (error: any) {
      console.error('Failed to delete order:', error);
      setToastMessage(error.response?.data?.message || 'Failed to delete order');
      setToastType('error');
      setShowToast(true);
    }
  };

  const addItem = () => {
    setFormData({
      ...formData,
      items: [...formData.items, { product_id: 0, quantity: 1, unit_price: 0 }]
    });
  };

  const removeItem = (index: number) => {
    setFormData({
      ...formData,
      items: formData.items.filter((_, i) => i !== index)
    });
  };

  const updateItem = (index: number, field: string, value: any) => {
    const newItems = [...formData.items];
    newItems[index] = { ...newItems[index], [field]: value };
    setFormData({ ...formData, items: newItems });
  };

  const resetForm = () => {
    setFormData({
      supplier_id: 0,
      delivery_address: '',
      notes: '',
      items: []
    });
    setEmployeeFormData({
      entity_name: user?.full_name || user?.username || '',
      fund_cluster: '',
      office_section: user?.department || '',
      responsibility_center_code: '',
      date: new Date().toLocaleDateString('en-US', { month: '2-digit', day: '2-digit', year: 'numeric' }).replace(/\//g, '/'),
      remark: '',
      items: Array(4).fill(null).map(() => ({
        unit: '',
        item_description: '',
        quantity: 0,
        unit_cost: 0.0,
        total_cost: 0.0
      }))
    });
    setErrors({});
    setEditingOrder(null);
  };

  const handleShowModal = () => {
    resetForm();
    setShowModal(true);
  };

  const handleCloseModal = () => {
    setShowModal(false);
    resetForm();
  };

  const formatCurrency = (amount: number): string => {
    return new Intl.NumberFormat('en-PH', {
      style: 'currency',
      currency: 'PHP',
    }).format(amount);
  };

  const formatDate = (dateString: string): string => {
    return new Date(dateString).toLocaleDateString('en-PH');
  };

  const getStatusBadge = (status: string) => {
    const statusConfig: { [key: string]: { variant: string; text: string } } = {
      'Draft': { variant: 'secondary', text: 'Draft' },
      'Pending': { variant: 'warning', text: 'Pending' },
      'Approved': { variant: 'success', text: 'Approved' },
      'Completed': { variant: 'primary', text: 'Completed' },
      'Cancelled': { variant: 'danger', text: 'Cancelled' },
    };

    const config = statusConfig[status] || { 
      variant: 'secondary', 
      text: status 
    };

    return <Badge bg={config.variant}>{config.text}</Badge>;
  };

  return (
    <Container fluid className="py-5">
      {error && (
        <Row className="mb-4">
          <Col>
            <div className="alert alert-danger alert-dismissible fade show" role="alert">
              <i className="bi bi-exclamation-circle me-2"></i>
              {error}
            </div>
          </Col>
        </Row>
      )}

      {/* Header Section */}
      <Row className="mb-5">
        <Col>
          <div className="d-flex justify-content-between align-items-center">
            <div>
              <h1 className="fw-bold text-dark mb-2">
                <i className="bi bi-cart text-primary me-3"></i>
                Purchase Orders
              </h1>
              <p className="text-muted fs-6">Manage and track purchase orders</p>
            </div>
            <Button
              variant="primary"
              size="lg"
              onClick={() => setShowModal(true)}
              className="px-4 py-2"
            >
              <i className="bi bi-plus-circle me-2"></i>
              New Order
            </Button>
          </div>
        </Col>
      </Row>

      {/* Search Section */}
      <Row className="mb-4">
        <Col md={6}>
          <InputGroup>
            <InputGroup.Text className="bg-light border-light">
              <i className="bi bi-search"></i>
            </InputGroup.Text>
            <Form.Control
              placeholder="Search by PO number or supplier..."
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              className="border-light"
            />
          </InputGroup>
        </Col>
      </Row>

      {/* Orders Table Section */}
      <Row>
        <Col>
          <Card className="border-0 shadow-sm rounded-lg overflow-hidden">
            <Card.Body className="p-0">
              <div style={{ overflowX: 'auto' }}>
                <Table hover className="mb-0 table-striped">
                  <thead className="bg-light border-bottom">
                    <tr>
                      <th className="fw-bold text-dark">PO Number</th>
                      <th className="fw-bold text-dark">Supplier</th>
                      <th className="fw-bold text-dark">Date</th>
                      <th className="fw-bold text-dark text-end">Total Amount</th>
                      <th className="fw-bold text-dark text-center">Status</th>
                      <th className="fw-bold text-dark text-center">Action</th>
                    </tr>
                  </thead>
                  <tbody>
                    {filteredOrders.length === 0 ? (
                      <tr>
                        <td colSpan={6} className="text-center py-5 text-muted">
                          <i className="bi bi-inbox fs-1 d-block mb-2"></i>
                          <span>No orders found</span>
                        </td>
                      </tr>
                    ) : (
                      filteredOrders.map((order) => (
                        <tr key={order.id} className="align-middle">
                          <td className="fw-bold text-primary">{order.po_number}</td>
                          <td>{order.supplier}</td>
                          <td>
                            <small>{new Date(order.order_date).toLocaleDateString()}</small>
                          </td>
                          <td className="text-end">
                            <span className="fw-bold text-success">₱{order.total_amount.toFixed(2)}</span>
                          </td>
                          <td className="text-center">
                            <Badge bg={order.status === 'Completed' ? 'success' : order.status === 'Approved' ? 'info' : 'warning'} className="px-3 py-2">
                              {order.status}
                            </Badge>
                          </td>
                          <td className="text-center">
                            <Button
                              variant="outline-info"
                              size="sm"
                              className="rounded-circle"
                              style={{ width: '36px', height: '36px', padding: 0 }}
                            >
                              <i className="bi bi-eye"></i>
                            </Button>
                          </td>
                        </tr>
                      ))
                    )}
                  </tbody>
                </Table>
              </div>
            </Card.Body>
          </Card>
        </Col>
      </Row>

      {/* Create Order Modal */}
      <Modal show={showModal} onHide={() => setShowModal(false)} size="lg" centered>
        <Modal.Header closeButton className="bg-light border-bottom">
          <Modal.Title className="fw-bold">
            <i className="bi bi-file-earmark-plus text-primary me-2"></i>
            New Purchase Order
          </Modal.Title>
        </Modal.Header>
        <Modal.Body className="p-4">
          <Form>
            <Row className="g-3 mb-4">
              <Col md={6}>
                <Form.Group>
                  <Form.Label className="fw-bold small">PO Number *</Form.Label>
                  <Form.Control
                    value={currentOrder.po_number}
                    onChange={(e) => setCurrentOrder({ ...currentOrder, po_number: e.target.value })}
                    placeholder="e.g., PO-2026-001"
                    size="sm"
                    className="border-light"
                  />
                </Form.Group>
              </Col>
              <Col md={6}>
                <Form.Group>
                  <Form.Label className="fw-bold small">Supplier *</Form.Label>
                  <Form.Control
                    value={currentOrder.supplier}
                    onChange={(e) => setCurrentOrder({ ...currentOrder, supplier: e.target.value })}
                    placeholder="Supplier name"
                    size="sm"
                    className="border-light"
                  />
                </Form.Group>
              </Col>
            </Row>

            <Row className="g-3 mb-4">
              <Col md={6}>
                <Form.Group>
                  <Form.Label className="fw-bold small">Order Date *</Form.Label>
                  <Form.Control
                    type="date"
                    value={currentOrder.order_date}
                    onChange={(e) => setCurrentOrder({ ...currentOrder, order_date: e.target.value })}
                    size="sm"
                    className="border-light"
                  />
                </Form.Group>
              </Col>
              <Col md={6}>
                <Form.Group>
                  <Form.Label className="fw-bold small">Status</Form.Label>
                  <Form.Select
                    value={currentOrder.status}
                    onChange={(e) => setCurrentOrder({ ...currentOrder, status: e.target.value as any })}
                    size="sm"
                    className="border-light"
                  >
                    <option value="Draft">Draft</option>
                    <option value="Pending">Pending</option>
                    <option value="Approved">Approved</option>
                    <option value="Completed">Completed</option>
                  </Form.Select>
                </Form.Group>
              </Col>
            </Row>

            <Form.Group className="mb-4">
              <Form.Label className="fw-bold small">Notes</Form.Label>
              <Form.Control
                as="textarea"
                rows={3}
                value={currentOrder.notes}
                onChange={(e) => setCurrentOrder({ ...currentOrder, notes: e.target.value })}
                placeholder="Additional notes"
                size="sm"
                className="border-light"
              />
            </Form.Group>
          </Form>
        </Modal.Body>
        <Modal.Footer className="bg-light border-top">
          <Button variant="secondary" onClick={() => setShowModal(false)}>
            Cancel
          </Button>
          <Button variant="primary" onClick={handleSave} className="px-4">
            <i className="bi bi-check-circle me-2"></i>
            Save Order
          </Button>
        </Modal.Footer>
      </Modal>

      <Toast
        show={showToast}
        onClose={() => setShowToast(false)}
        message={toastMessage}
        type={toastType}
        delay={3000}
      />
    </Container>
  );
};

export default Orders;
